package com.gittexplorer.documentextractor.controller;
import com.gittexplorer.documentextractor.dto.DocumentExtractionResponse;import com.gittexplorer.documentextractor.service.DocumentService;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.media.Content;import io.swagger.v3.oas.annotations.media.Schema;import io.swagger.v3.oas.annotations.parameters.RequestBody;import io.swagger.v3.oas.annotations.responses.ApiResponse;import org.springframework.http.MediaType;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RequestPart;import org.springframework.web.bind.annotation.RestController;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/v1/documents") public class DocumentController { private final DocumentService documentService; public DocumentController(DocumentService documentService){this.documentService=documentService;} @Operation(summary="Extract text and identifiers from uploaded documents",requestBody=@RequestBody(content=@Content(mediaType=MediaType.MULTIPART_FORM_DATA_VALUE)),responses=@ApiResponse(responseCode="200",description="Extraction completed",content=@Content(schema=@Schema(implementation=DocumentExtractionResponse.class)))) @PostMapping(value="/extract",consumes=MediaType.MULTIPART_FORM_DATA_VALUE,produces=MediaType.APPLICATION_JSON_VALUE) public DocumentExtractionResponse extract(@RequestPart("files") MultipartFile[] files){return documentService.extract(files);} }
